"use client";

import React, { useState } from "react";
import * as LucideIcons from "lucide-react";

// Safe icon renderer
function Icon({ name, className }: { name: string, className?: string }) {
    const LucideIcon = (LucideIcons as any)[name];
    if (!LucideIcon) return <div className={className} style={{ width: '20px', height: '20px', backgroundColor: '#333', borderRadius: '4px' }} />;
    return <LucideIcon className={className} />;
}

export default function AdminRelatorios() {
    const stats = [
        { label: "Faturamento Mensal", value: "R$ 15.420", color: "text-[#D4AF37]", icon: "DollarSign", change: "+18%" },
        { label: "Clientes Ativos", value: "247", color: "text-[#D4AF37]", icon: "Users", change: "+12%" },
        { label: "Serviços Realizados", value: "89", color: "text-[#D4AF37]", icon: "Scissors", change: "+5%" },
    ];

    const chartData = [12000, 14000, 16000, 15000, 17000, 18500];
    const maxVal = Math.max(...chartData);

    return (
        <div className="min-h-screen bg-[#0a0a0a] text-white p-6 lg:p-12 font-sans selection:bg-[#D4AF37] selection:text-black animate-fade-in-up">
            <div className="max-w-5xl mx-auto bg-[#111111] border border-[#1f1f1f] rounded-3xl p-8 shadow-2xl h-[calc(100vh-100px)] overflow-y-auto custom-scrollbar">
                <header className="flex justify-between items-center mb-10">
                    <div className="flex items-center gap-3">
                        <Icon name="BarChart3" className="w-6 h-6 text-[#D4AF37]" />
                        <h2 className="text-2xl font-bold tracking-tight">Relatórios</h2>
                    </div>
                </header>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-10">
                    {stats.map((stat, i) => (
                        <div key={i} className="bg-[#1a1a1a] border border-[#222] p-6 rounded-2xl relative overflow-hidden group">
                            <div className="flex justify-between items-start mb-4">
                                <Icon name={stat.icon} className={`w-5 h-5 ${stat.color}`} />
                                <span className="text-emerald-500 text-[10px] font-bold flex items-center gap-1">
                                    <Icon name="TrendingUp" className="w-3 h-3" /> {stat.change}
                                </span>
                            </div>
                            <h3 className="text-2xl font-bold text-white mb-1">{stat.value}</h3>
                            <p className="text-gray-500 text-[10px] uppercase font-bold tracking-widest">{stat.label}</p>
                        </div>
                    ))}
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-10">
                    <div className="bg-[#1a1a1a] border border-[#222] p-8 rounded-3xl">
                        <h4 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-10">Faturamento Mensal</h4>
                        <div className="flex items-end justify-between h-56 gap-2">
                            {['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun'].map((month, i) => (
                                <div key={i} className="flex-1 flex flex-col items-center gap-4">
                                    <div
                                        className="w-full bg-[#D4AF37] rounded-t-lg transition-all duration-1000"
                                        style={{ height: `${(chartData[i] / maxVal) * 100}%` }}
                                    />
                                    <span className="text-[10px] text-gray-500 font-bold uppercase">{month}</span>
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="bg-[#1a1a1a] border border-[#222] p-8 rounded-3xl flex flex-col items-center">
                        <h4 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-10 w-full">Serviços Mais Vendidos</h4>
                        <div className="relative w-48 h-48 mb-10">
                            {/* Donut Chart Simulation */}
                            <div className="absolute inset-0 rounded-full border-[20px] border-[#D4AF37] border-r-[#b5952f] border-b-[#8c7425] border-l-gray-600 rotate-45" />
                            <div className="absolute inset-0 rounded-full flex items-center justify-center">
                                <div className="w-28 h-28 bg-[#1a1a1a] rounded-full" />
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-x-8 gap-y-3 w-full">
                            {[
                                { label: "Corte + Barba", color: "bg-[#D4AF37]" },
                                { label: "Corte Degradê", color: "bg-[#b5952f]" },
                                { label: "Barba", color: "bg-[#8c7425]" },
                                { label: "Corte Social", color: "bg-gray-600" }
                            ].map((item, i) => (
                                <div key={i} className="flex items-center gap-2">
                                    <div className={`w-2 h-2 rounded-full ${item.color}`} />
                                    <span className="text-[10px] text-gray-400 font-bold uppercase">{item.label}</span>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                <div className="bg-[#1a1a1a] border border-[#222] p-8 rounded-3xl">
                    <h4 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-8">Desempenho por Barbeiro</h4>
                    <div className="space-y-6">
                        {[
                            { name: "Carlos Silva", clients: 42, rev: "R$ 5.200", rating: 4.9 },
                            { name: "André Souza", clients: 38, rev: "R$ 4.850", rating: 4.8 },
                            { name: "Felipe Dias", clients: 35, rev: "R$ 4.100", rating: 5.0 },
                        ].map((barber, i) => (
                            <div key={i} className="flex items-center justify-between border-b border-[#222] pb-4 last:border-0 last:pb-0">
                                <div className="flex items-center gap-4">
                                    <div className="w-8 h-8 rounded-lg bg-[#D4AF37]/10 flex items-center justify-center text-[#D4AF37] font-bold text-xs">{i + 1}</div>
                                    <h5 className="font-bold text-sm">{barber.name}</h5>
                                </div>
                                <div className="flex items-center gap-10">
                                    <span className="text-[10px] text-gray-500 font-bold uppercase">{barber.clients} clientes</span>
                                    <span className="text-[#D4AF37] font-bold text-sm tracking-tighter">{barber.rev}</span>
                                    <span className="text-[#D4AF37] font-bold text-sm">★ {barber.rating}</span>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
}
